import os, re

def load_grids():
    d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read()
    G = {}
    # Find all Demo pair inputs/outputs and Test input
    pattern = r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n'
    for m in re.finditer(pattern, t):
        key = m[1]
        h, w = int(m[2]), int(m[3])
        rows = [r.split() for r in t[m.end():].split('\n')[:h]]
        if key not in G:
            valid = all(len(r) == w and all(x.isdigit() for x in r) for r in rows)
            if valid:
                G[key] = [[int(x) for x in r] for r in rows]
    return G

G = load_grids()
print("Available grids:", sorted(G.keys()))
for k in G:
    print(f"\n=== {k} ===")
    for row in G[k]:
