import os, re, json

RLM_SESSION_DIR = os.environ.get('RLM_SESSION_DIR', '')
sessions_dir = f"{RLM_SESSION_DIR}/../../sessions/"
jsonl_path = os.path.join(sessions_dir, os.path.basename(RLM_SESSION_DIR) + '.jsonl')

with open(jsonl_path, 'r') as f:
    lines = f.readlines()

# Extract all texts from user role messages and print them
for i, line in enumerate(lines):
    try:
        msg = json.loads(line)
        if msg.get('role') == 'user':
            content_parts = msg.get('content', [])
            full_text = ""
            for part in content_parts:
                if isinstance(part, dict) and part.get('type') == 'text':
                    full_text += part.get('text', '')

            # Search for Demo pair patterns specifically
            demos = re.findall(r'Demo pair \d+ (?:input|output) \((\d+)x(\d+)\):(.*?)$', full_text, re.MULTILINE | re.DOTALL)
            tests = re.findall(r'Test input \((\d+)x(\d+)\):(.*?)$', full_text, re.MULTILINE | re.DOTALL)

            if demos or tests:
                print(f"\n=== Message {i} ===")
                # Print just the demo/test parts
                for match_type in [demos, tests]:
                    for match in match_type:
                        print(f"Key: {match[0]}, Dims: {match[1]}")
                        rows_str = '\n'.join(match[2].split('\n')[:min(len(match[2].strip().split('\n')), min(int(match[1])+3, 10))])
                        print("Grid preview:")
                        print(rows_str)
    except Exception as e:
        pass

