            for part in msg.get('content', []):
                if isinstance(part, dict) and part.get('type') == 'text':
                    texts.append(part.get('text', ''))
            combined = ''.join(texts)

            # Look for key patterns
            if 'Demo pair' in combined or 'Test input' in combined:
                print(f"\n=== Message {i} ===")
                print(combined[:2000])
    except Exception as e:
        pass

